/**
 * Key numbers in a row or grid: plain figures, cards (StatTile) or figures with an icon. Axes: columns (2, 3,
 * 4), item (plain, card, icon), surface (none, image, panel: one rounded card), align, density, tone. Title may
 * be empty.
 */
import { type ReactNode } from "react";
import { Grid } from "../primitives/grid/grid";
import { Backdrop } from "../components/backdrop";
import { SectionFrame } from "../components/section-frame";
import { StatFigure } from "../components/stat-figure";
import { defaults } from "../presets/defaults";
import { cn } from "../utils";
import type { Stat } from "./stats-band.types";

export type StatsBandProps = {
  id: string;
  title?: string;
  stats: Stat[];
  cols?: "2" | "3" | "4";
  layout?: "row" | "stack";
  surface?: "none" | "image" | "panel";
  item?: "plain" | "card" | "icon";
  align?: "start" | "center";
  tone?: "default" | "muted";
  density?: "roomy" | "default" | "compact";
};

export function StatsBand({
  id,
  title = "",
  stats,
  cols = "4",
  layout = "row",
  surface = "none",
  item = "plain",
  align = "center",
  tone = "default",
  density = "default",
}: StatsBandProps) {
  return (
    <Backdrop kind={(((surface as string) === "image") ? "image" : "none")} alt={title}>
      <SectionFrame
        id={id}
        title={title}
        tone={tone}
        density={density}
        align={align}
        measure={
          (surface as string) === "panel" ? "fill"
          : (layout as string) === "stack" ? "xs"
          : "default"
        }
        className={cn(
          (((surface as string) === "image") ? "bg-transparent" : ""),
          (((surface as string) === "panel") ? "py-0" : "")
        )}
      >
        {((surface as string) === "panel") ? (
          <Grid
            cols={
              (cols as string) === "2" ? "2"
              : (cols as string) === "3" ? "2-3"
              : (cols as string) === "4" ? "2-4"
              : "3-6"
            }
            className={cn("w-full items-center bg-muted px-6", defaults.stats.panel)}
            data-testid="items"
          >
            {(stats ?? []).map((stat) => (
              <StatFigure key={stat.id} stat={stat} item={item} align={align} />
            ))}
          </Grid>
        ) : (
          <Grid
            cols={
              (layout as string) === "stack" ? "1"
              : (cols as string) === "2" ? "2"
              : (cols as string) === "3" ? "2-3"
              : (cols as string) === "4" ? "2-4"
              : "3-6"
            }
            className="gap-6"
            data-testid="items"
          >
            {(stats ?? []).map((stat) => (
              <StatFigure key={stat.id} stat={stat} item={item} align={align} />
            ))}
          </Grid>
        )}
      </SectionFrame>
    </Backdrop>
  );
}

